// Returns the first element; throws InvalidOperationException if empty.
int first = numbers.First();          // ✅ 10
// empty.First();                     // ❌ throws – sequence contains no elements

// ── FirstOrDefault() ────────────────────────────────────────────────────────
// Returns the first element OR the type default if empty. Never throws.
int firstOrDef = empty.FirstOrDefault();        // ✅ 0  (default for int)
int firstOrDef2 = empty.FirstOrDefault(-1);     // ✅ -1 (custom default, .NET 6+)

// ── Single() ────────────────────────────────────────────────────────────────
// Exactly ONE element must exist – throws if 0 or >1 elements match.
int onlyOne = single.Single();        // ✅ 42
