using System.Collections.Concurrent;
using System.Threading.Tasks;

public class ConcurrentDictionaryDemo
{
    // Shared cache — safe to read/write from multiple threads
    private static readonly ConcurrentDictionary<string, int> _wordCount
        = new ConcurrentDictionary<string, int>(
            concurrencyLevel: Environment.ProcessorCount,  // number of lock stripes
            capacity: 1024);

    public static async Task Main()
    {
        string[] words = { "apple", "banana", "apple", "cherry", "banana", "apple" };

        // Parallel word count — no manual locking required
        Parallel.ForEach(words, word =>
        {
            // AddOrUpdate is atomic: read-modify-write in one operation
            _wordCount.AddOrUpdate(
                key: word,
                addValue: 1,                    // value if key is new
                updateValueFactory: (key, old) => old + 1); // update if exists
        });

        foreach (var (word, count) in _wordCount)
            Console.WriteLine($"{word}: {count}");

        // -------------------------------------------------------------------
        // GetOrAdd — use for lazy initialization / caching
        // WARNING: factory delegate may run more than once; keep it side-effect-free
        // -------------------------------------------------------------------
        var cache = new ConcurrentDictionary<int, string>();

