// ─── Domain Layer ───────────────────────────────────────────────────────────
public class User
{
    public Guid Id { get; private set; }
    public string Email { get; private set; }
    public bool IsActive { get; private set; }

    public User(Guid id, string email)
    {
        Id = id;
        Email = email;
        IsActive = true;
    }

    public void Deactivate() => IsActive = false;
}

// ─── Repository Interface (Application/Domain Layer) ────────────────────────
// NOTE: Returns domain objects, NOT IQueryable — avoids leaky abstraction
public interface IUserRepository
{
    Task<User?> GetByIdAsync(Guid id, CancellationToken ct = default);
    Task<IReadOnlyList<User>> GetAllActiveAsync(CancellationToken ct = default);
    Task AddAsync(User user, CancellationToken ct = default);
    Task UpdateAsync(User user, CancellationToken ct = default);
    Task DeleteAsync(Guid id, CancellationToken ct = default);
}

// ─── Infrastructure: EF Core Implementation ─────────────────────────────────
public class EfUserRepository : IUserRepository
{
    private readonly AppDbContext _db;

    public EfUserRepository(AppDbContext db) => _db = db;

    public async Task<User?> GetByIdAsync(Guid id, CancellationToken ct = default)
        => await _db.Users.AsNoTracking().FirstOrDefaultAsync(u => u.Id == id, ct);

    public async Task<IReadOnlyList<User>> GetAllActiveAsync(CancellationToken ct = default)
        => await _db.Users.Where(u => u.IsActive).AsNoTracking().ToListAsync(ct);

    public async Task AddAsync(User user, CancellationToken ct = default)
    {
        await _db.Users.AddAsync(user, ct);
        await _db.SaveChangesAsync(ct);
    }

    public async Task UpdateAsync(User user, CancellationToken ct = default)
    {
        _db.Users.Update(user);
        await _db.SaveChangesAsync(ct);
    }

    public async Task DeleteAsync(Guid id, CancellationToken ct = default)
    {
        var user = await _db.Users.FindAsync(new object[] { id }, ct);
        if (user is not null)
        {
            _db.Users.Remove(user);
            await _db.SaveChangesAsync(ct);
        }
    }
}

