public record Employee(string FirstName, string LastName, int Age, string Department)
    : Person(FirstName, LastName, Age)  // records support inheritance
{
    // Computed property — not part of equality (only constructor params are)
    // Wait: ALL properties are part of equality for records. 
    // If you want to EXCLUDE a property, override Equals manually or use a field.
    public string FullName => $"{FirstName} {LastName}";

    // Custom validation in a record
    public Employee
    {
        // Primary constructor body (C# 9+ feature for records)
        if (Age < 18) throw new ArgumentException("Employee must be 18+", nameof(Age));
        Department = Department.Trim();
    }
}

