using Polly.CircuitBreaker;
using System.Net.Http;

// ── 1. Basic Circuit Breaker (count-based) ──────────────────────────────────
// Trips after 3 consecutive failures; stays open for 30 seconds.
var basicCircuitBreaker = Policy
    .Handle<HttpRequestException>()
    .CircuitBreaker(
        exceptionsAllowedBeforeBreaking: 3,
        durationOfBreak: TimeSpan.FromSeconds(30),
        onBreak: (exception, duration) =>
            Console.WriteLine($"Circuit OPENED for {duration.TotalSeconds}s. Reason: {exception.Message}"),
        onReset: () =>
            Console.WriteLine("Circuit CLOSED — service recovered."),
        onHalfOpen: () =>
            Console.WriteLine("Circuit HALF-OPEN — probing service...")
    );

// ── 2. Advanced: Advanced Circuit Breaker (rate-based, more production-ready) ─
// Trips if 50%+ of calls fail within a 10-second window (min 5 calls sampled).
var advancedCircuitBreaker = Policy
    .Handle<HttpRequestException>()
    .OrResult<HttpResponseMessage>(r => !r.IsSuccessStatusCode)
    .AdvancedCircuitBreaker(
        failureThreshold: 0.5,            // 50% failure rate
        samplingDuration: TimeSpan.FromSeconds(10),
        minimumThroughput: 5,             // need at least 5 calls in the window
        durationOfBreak: TimeSpan.FromSeconds(30),
        onBreak: (outcome, state, duration, context) =>
            Console.WriteLine($"[{context.PolicyKey}] Circuit opened. State: {state}"),
        onReset: context =>
            Console.WriteLine($"[{context.PolicyKey}] Circuit reset."),
        onHalfOpen: () =>
            Console.WriteLine("Probing downstream...")
    );

// ── 3. Combining with Retry + Fallback (real-world policy wrap) ──────────────
var fallback = Policy<string>
    .Handle<BrokenCircuitException>()
    .Fallback(
        fallbackValue: "{ \"status\": \"degraded\", \"source\": \"cache\" }",
        onFallback: (ex, ctx) => Console.WriteLine("Returning cached fallback response.")
    );

var retry = Policy
    .Handle<HttpRequestException>() // only retry transient errors, NOT BrokenCircuitException
    .WaitAndRetry(2, attempt => TimeSpan.FromMilliseconds(200 * attempt));

var circuitBreaker = Policy
    .Handle<HttpRequestException>()
