//        OpenTelemetry.Instrumentation.Http, OpenTelemetry.Exporter.OpenTelemetryProtocol

// Program.cs
var builder = WebApplication.CreateBuilder(args);

builder.Services.AddOpenTelemetry()
    .WithTracing(tracing => tracing
        .SetResourceBuilder(ResourceBuilder.CreateDefault()
            .AddService(serviceName: "OrderService", serviceVersion: "2.1.0"))

        // Auto-instrument incoming HTTP requests
        .AddAspNetCoreInstrumentation(opts =>
        {
            opts.RecordException = true;
            opts.Filter = ctx => !ctx.Request.Path.StartsWithSegments("/health");
        })

        // Auto-instrument outbound HttpClient calls
        .AddHttpClientInstrumentation()

        // Auto-instrument Entity Framework Core queries
        .AddEntityFrameworkCoreInstrumentation(opts =>
            opts.SetDbStatementForText = true)

        // Export to OTel Collector (which forwards to Jaeger)
        .AddOtlpExporter(opts =>
        {
            opts.Endpoint = new Uri("http://otel-collector:4317");
            opts.Protocol = OtlpExportProtocol.Grpc;
        })

        // Head-based sampling: 10% in production, 100% in dev
        .SetSampler(builder.Environment.IsDevelopment()
            ? new AlwaysOnSampler()
            : new TraceIdRatioBasedSampler(0.1))
    )
    .WithMetrics(metrics => metrics
        .AddAspNetCoreInstrumentation()
        .AddRuntimeInstrumentation()
        .AddOtlpExporter());

var app = builder.Build();

