const UPLOAD_DIR = "./uploads";
const MAX_FILE_SIZE = 50 * 1024 * 1024; // 50 MB
const ALLOWED_MIME_TYPES = new Set(["image/jpeg", "image/png", "application/pdf"]);

// Magic bytes for basic content sniffing (first 4 bytes)
const MAGIC_BYTES = {
  "image/jpeg": [0xff, 0xd8, 0xff],
  "image/png":  [0x89, 0x50, 0x4e, 0x47],
  "application/pdf": [0x25, 0x50, 0x44, 0x46],
};

// In-memory progress store — use Redis in production
const progressMap = new Map(); // sessionId -> { sent, total, status }

// ── 1. SSE endpoint — client subscribes before uploading ──────────────────────
app.get("/upload/progress/:sessionId", (req, res) => {
  const { sessionId } = req.params;

  res.setHeader("Content-Type", "text/event-stream");
  res.setHeader("Cache-Control", "no-cache");
  res.setHeader("Connection", "keep-alive");
  res.flushHeaders();

  // Send initial heartbeat so the client knows the channel is live
  res.write("data: {\"status\":\"connected\"}\n\n");

  // Poll internal progress state and push to client
  const interval = setInterval(() => {
    const progress = progressMap.get(sessionId);
    if (!progress) return;

    res.write(`data: ${JSON.stringify(progress)}\n\n`);

    if (progress.status === "done" || progress.status === "error") {
      clearInterval(interval);
      res.end();
      progressMap.delete(sessionId);
    }
  }, 200); // 200ms granularity — tune to taste

  req.on("close", () => clearInterval(interval));
});

