public async Task TransferFundsAsync(int fromId, int toId, decimal amount)
{
    // ✅ Open connection only when needed, dispose immediately after
    await using var context = await _dbContextFactory.CreateDbContextAsync();
    await using var tx = await context.Database.BeginTransactionAsync();
    try
    {
        // Do ALL reads + writes inside the transaction block — no external I/O
        var from = await context.Accounts.FindAsync(fromId);
        var to   = await context.Accounts.FindAsync(toId);
        from!.Balance -= amount;
        to!.Balance   += amount;
        await context.SaveChangesAsync();
        await tx.CommitAsync();
    }
    catch
    {
        await tx.RollbackAsync();
        throw;
    }
    // DbContext disposed here → connection returned to pool immediately
}

