}

interface User {
  id: number;
  name: string;
}

const userResponse: ApiResponse<User> = {
  data: { id: 1, name: "Alice" },
  status: 200,
  message: "OK",
};

// TypeScript knows userResponse.data.name is a string — full IntelliSense
console.log(userResponse.data.name.toUpperCase()); // ✅

