  return (
    <form onSubmit={handleSubmit}>
      <input value={query} onChange={handleChange} placeholder="Search..." />
      <button type="submit">Go</button>
    </form>
  );
}

// ─── 3. Passing arguments to handlers ───────────────────────────────────────
