// main.jsx — App entry point
import { createBrowserRouter, RouterProvider } from "react-router-dom";
import { lazy, Suspense } from "react";
import RootLayout from "./layouts/RootLayout";
import ErrorPage from "./pages/ErrorPage";

// ✅ Lazy-loaded pages for code splitting
const Home = lazy(() => import("./pages/Home"));
const UserList = lazy(() => import("./pages/UserList"));
const UserDetail = lazy(() => import("./pages/UserDetail"));

// ✅ Data router: loaders run before component renders (v6.4+)
const router = createBrowserRouter([
  {
    path: "/",
    element: <RootLayout />,        // persistent shell (nav, footer)
    errorElement: <ErrorPage />,    // catches loader/render errors
    children: [
      {
        index: true,                // matches exactly "/"
        element: <Suspense fallback={<p>Loading...</p>}><Home /></Suspense>,
      },
      {
        path: "users",
        element: <Suspense fallback={<p>Loading...</p>}><UserList /></Suspense>,
        loader: async () => {
          // runs server-side (or client) before render; auto-cancels on navigation
          const res = await fetch("/api/users");
          if (!res.ok) throw new Response("Failed", { status: 500 });
          return res.json();         // accessed via useLoaderData()
        },
      },
      {
        path: "users/:userId",       // :userId = URL param
        element: <Suspense fallback={<p>Loading...</p>}><UserDetail /></Suspense>,
        loader: async ({ params }) => {
          const res = await fetch(`/api/users/${params.userId}`);
          if (!res.ok) throw new Response("Not Found", { status: 404 });
          return res.json();
        },
      },
    ],
  },
]);

export default function App() {
  return <RouterProvider router={router} />;
}

