// when using `export const dynamic = 'force-dynamic'` or cookies/headers

import { notFound } from "next/navigation";

interface Product {
  id: number;
  title: string;
  price: number;
  description: string;
}

// Simulate a DB / API call
async function getProduct(id: string): Promise<Product | null> {
  const res = await fetch(`https://fakestoreapi.com/products/${id}`, {
    // "no-store" opts out of caching → true SSR (fresh on every request)
    cache: "no-store",
  });
  if (!res.ok) return null;
  return res.json();
}

// Next.js renders this component on the server and streams the HTML
export default async function ProductPage({
  params,
}: {
  params: { id: string };
}) {
  const product = await getProduct(params.id);

  if (!product) notFound(); // returns a 404 HTML response from the server

  return (
    <main>
      <h1>{product.title}</h1>
      <p>${product.price}</p>
      <p>{product.description}</p>
    </main>
  );
}

