    <div>
      <input value={query} onChange={handleChange} placeholder="Search..." />
      {/* Show a loading indicator while the deferred render is in progress */}
      {isPending && <p>Updating results...</p>}
      <ul>
        {filtered.map((item) => (
          <li key={item}>{item}</li>
        ))}
      </ul>
    </div>
  );
}

