// === auth/AuthContext.tsx ===
import React, { createContext, useContext, useState } from "react";

interface AuthContextType {
  user: { name: string; role: string } | null;
  isLoading: boolean;
  login: (token: string) => void;
  logout: () => void;
}

const AuthContext = createContext<AuthContextType | null>(null);

export const AuthProvider = ({ children }: { children: React.ReactNode }) => {
  // In production, initialize from localStorage/cookie and validate with server
  const [user, setUser] = useState<{ name: string; role: string } | null>(null);
  const [isLoading] = useState(false); // would be true while validating stored token

  const login = (_token: string) => {
    // In production: decode JWT or call /me endpoint
    setUser({ name: "Alice", role: "admin" });
  };

  const logout = () => setUser(null);

  return (
    <AuthContext.Provider value={{ user, isLoading, login, logout }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error("useAuth must be used within AuthProvider");
  return ctx;
};

// === components/ProtectedRoute.tsx ===
import { Navigate, Outlet, useLocation } from "react-router-dom";
import { useAuth } from "../auth/AuthContext";

interface ProtectedRouteProps {
  requiredRole?: string; // optional role-based access control
}

export const ProtectedRoute = ({ requiredRole }: ProtectedRouteProps) => {
  const { user, isLoading } = useAuth();
  const location = useLocation();

  // Avoid flash-redirect while async auth check is in flight
  if (isLoading) return <div>Loading...</div>;

  // Not logged in → redirect to /login, preserving the intended URL
  if (!user) {
    return <Navigate to="/login" state={{ from: location }} replace />;
  }

  // Logged in but wrong role → redirect to unauthorized page
  if (requiredRole && user.role !== requiredRole) {
    return <Navigate to="/unauthorized" replace />;
  }

  // Auth passed → render the child route
  return <Outlet />;
};

