-- SET-BASED EQUIVALENT (always prefer this when possible)
-- ===========================================================
/*
UPDATE e
SET    Salary = Salary + (Salary * CASE
           WHEN DepartmentID = 10 THEN 0.05
           WHEN DepartmentID = 20 THEN 0.08
           
