-- ============================================================
-- PARTIAL UNIQUE INDEX -- enforce business rule:
-- a user can have at most ONE 'active' subscription at a time
-- ============================================================
CREATE TABLE subscriptions (
    id         BIGSERIAL PRIMARY KEY,
    user_id    BIGINT      NOT NULL,
    plan       VARCHAR(50) NOT NULL,
    is_active  BOOLEAN     NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Full unique index on (user_id) would prevent multiple cancelled subs.
-- Partial unique index: uniqueness ONLY enforced among active rows.
CREATE UNIQUE INDEX idx_subscriptions_one_active_per_user
    ON subscriptions(user_id)
    WHERE is_active = TRUE;

-- This INSERT succeeds (first active sub):
INSERT INTO subscriptions(user_id, plan) VALUES (42, 'pro');

-- This INSERT fails with unique violation:
INSERT INTO subscriptions(user_id, plan) VALUES (42, 'enterprise');
-- ERROR: duplicate key value violates unique constraint

-- But a cancelled sub for the same user is always allowed:
INSERT INTO subscriptions(user_id, plan, is_active) VALUES (42, 'old-plan', FALSE);
-- OK

-- ============================================================
-- SQL SERVER EQUIVALENT (filtered index syntax is identical)
-- ============================================================
-- CREATE INDEX idx_orders_active
--     ON dbo.orders(status, created_at)
