    salesperson,
    MAX(CASE WHEN quarter = 'Q1' THEN revenue END) AS Q1_revenue,
    MAX(CASE WHEN quarter = 'Q2' THEN revenue END) AS Q2_revenue,
    MAX(CASE WHEN quarter = 'Q3' THEN revenue END) AS Q3_revenue,
    MAX(CASE WHEN quarter =
