// CACHE-ASIDE (most common pattern in practice)
// ─────────────────────────────────────────────
public async Task<Product?> GetProductAsync(int id)
{
    string key = $"product:{id}";

    // 1. Try cache first
    var cached = await _cache.GetStringAsync(key);
    if (cached is not null)
        return JsonSerializer.Deserialize<Product>(cached);

    // 2. Cache miss → hit the database
    var product = await _db.Products.FindAsync(id);
    if (product is null) return null;

    // 3. Populate cache with a TTL
    await _cache.SetStringAsync(key,
        JsonSerializer.Serialize(product),
        new DistributedCacheEntryOptions
        {
            AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(10)
        });

    return product;
}

public async Task UpdateProductAsync(Product product)
{
    // Write to DB first, then invalidate cache (not update)
    await _db.SaveChangesAsync();
    await _cache.RemoveAsync($"product:{product.Id}"); // Invalidate, not update
}

// ─────────────────────────────────────────────
// WRITE-THROUGH
// Cache + DB written synchronously on every write
// ─────────────────────────────────────────────
public async Task WriteThrough_UpdateProductAsync(Product product)
{
    string key = $"product:{product.Id}";
    string serialized = JsonSerializer.Serialize(product);

    // Write to DB synchronously
    _db.Products.Update(product);
    await _db.SaveChangesAsync();

    // Write to cache synchronously (before ACK to caller)
    await _cache.SetStringAsync(key, serialized,
        new DistributedCacheEntryOptions
        {
            AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(10)
        });
    // Both writes done → now return to caller
}

