// Example: Minimal API Gateway using YARP (Yet Another Reverse Proxy) in ASP.NET Core 8
// Install: dotnet add package Yarp.ReverseProxy

// Program.cs
var builder = WebApplication.CreateBuilder(args);

builder.Services.AddReverseProxy()
    .LoadFromConfig(builder.Configuration.GetSection("ReverseProxy"));

// Add cross-cutting middleware as services
builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme)
    .AddJwtBearer();
builder.Services.AddRateLimiter(options =>
{
    options.AddFixedWindowLimiter("global", o =>
    {
        o.PermitLimit = 100;
        o.Window = TimeSpan.FromSeconds(10);
    });
});

var app = builder.Build();

// Middleware pipeline — runs BEFORE routing to upstream
app.UseAuthentication();
app.UseAuthorization();
app.UseRateLimiter();

// Custom transform: inject correlation ID so all downstream services share it
app.Use(async (context, next) =>
{
    if (!context.Request.Headers.ContainsKey("X-Correlation-Id"))
        context.Request.Headers["X-Correlation-Id"] = Guid.NewGuid().ToString();
    await next();
});

app.MapReverseProxy(); // YARP handles routing + load balancing
app.Run();

