//        OpenTelemetry.Instrumentation.Http, OpenTelemetry.Exporter.Jaeger

// Program.cs
var builder = WebApplication.CreateBuilder(args);

builder.Services.AddOpenTelemetry()
    .WithTracing(tracing => tracing
        .SetResourceBuilder(
            ResourceBuilder.CreateDefault().AddService("OrderService"))
        // Auto-instrument: every inbound HTTP request becomes a root span
        .AddAspNetCoreInstrumentation()
        // Auto-instrument: every outbound HttpClient call becomes a child span
        .AddHttpClientInstrumentation()
        // Auto-instrument: EF Core queries become child spans
        .AddEntityFrameworkCoreInstrumentation()
        // Export via OTLP to OpenTelemetry Collector (or directly to Jaeger)
        .AddOtlpExporter(o =>
        {
            o.Endpoint = new Uri("http://otel-collector:4317");
            o.Protocol = OtlpExportProtocol.Grpc;
        }));

// ── Manual span for business logic you want to measure ──────────────────────

