    Task ExecuteAsync(JobContext context, CancellationToken ct);
}

public record JobContext(Guid JobId, string JobType, int AttemptNumber, Dictionary<string, string> Parameters);

// === 2. RETRY POLICY (Polly) ===
public static class RetryPolicies
{
    // Exponential backoff with jitter: 2s, 4s, 8s, 16s, 32s
    public static AsyncRetryPolicy BuildRetryPolicy(ILogger logger) =>
        Policy
            .Handle<Exception>(ex => ex is not OperationCanceledException)
            .WaitAndRetryAsync(
                retryCount: 5,
                sleepDurationProvider: attempt =>
                {
                    var baseDelay = TimeSpan.FromSeconds(Math.Pow(2, attempt));
                    var jitter = TimeSpan.FromMilliseconds(Random.Shared.Next(0, 1000));
                    return baseDelay + jitter; // prevents thundering herd
                },
                onRetry: (exception, delay, attempt, context) =>
                {
                    logger.Warning(
                        "Job {JobId} attempt {Attempt} failed. Retrying in {Delay}s. Error: {Error}",
                        context["JobId"], attempt, delay.TotalSeconds, exception.Message);

                    // Emit retry metric
                    JobMetrics.RetryCounter
                        .WithLabels(context["JobType"].ToString())
                        .Inc();
                });
}

