    """Level-order builder from a list (None = missing node)."""
    if not vals:
        return None
    nodes = [TreeNode(v) if v is not None else None for v in vals]
    kids = iter(nodes[1:])
    for node in nodes:
        if node:
            node.left  = next(kids, None)
            node.right = next(kids, None)
    return nodes[0]

