    assert search([1], 0) == -1
    assert search([1, 3], 3) == 1
    assert search([3, 1], 1) == 1   # pivot at index 1

    # With duplicates
    assert search_with_duplicates([2, 5, 6, 0, 0, 1, 2], 0) is True
    assert search_with_duplicates([2, 5, 6, 0, 0, 
