        int[] prev = new int[m + 1];
        int[] curr = new int[m + 1];

        for (int i = 0; i <= m; i++) prev[i] = i;

        for (int j = 1; j <= n; j++)
        {
            curr[0] = j;
            for (int i = 1; i <= m; i++)
            {
                if (s1[i - 1] == s2[j - 1])
