using Microsoft.AspNetCore.Authentication.JwtBearer;

var builder = WebApplication.CreateBuilder(args);

// 1. Register Entra ID authentication
//    appsettings.json must contain AzureAd: TenantId, ClientId, Audience
builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme)
    .AddMicrosoftIdentityWebApi(builder.Configuration.GetSection("AzureAd"))
    .EnableTokenAcquisitionToCallDownstreamApi()
    // 2. Allow this API to call Microsoft Graph on behalf of the user (OBO flow)
    .AddMicrosoftGraph(builder.Configuration.GetSection("MicrosoftGraph"))
    .AddInMemoryTokenCaches(); // Cache tokens to avoid re-acquiring every request

builder.Services.AddAuthorization(options =>
{
    // 3. Policy that requires the app role "Reports.Read"
    //    Roles are assigned in Entra ID App Registration -> App roles
    options.AddPolicy("ReportsRead", policy =>
        policy.RequireRole("Reports.Read"));
});

builder.Services.AddControllers();
var app = builder.Build();

app.UseAuthentication();
app.UseAuthorization();
app.MapControllers();
app.Run();

