// Access Key Vault — no connection string, no secret needed
var kvClient = new SecretClient(
    new Uri("https://my-keyvault.vault.azure.net/"),
    credential
);
KeyVaultSecret secret = await kvClient.GetSecretAsync("DatabasePassword");

// Access Blob Storage — same credential, just RBAC-assigned "Storage Blob Data Reader"
var blobClient = new BlobServiceClient(
    new Uri("https://mystorageaccount.blob.core.windows.net"),
    credential
);

// --- System-Assigned vs User-Assigned ---
// System-Assigned: enabled per resource, deleted when resource is deleted
// Use when: 1 resource → 1 identity, simple scenario

// User-Assigned: created as standalone ARM resource, assigned to 1+ resources
// Use when: multiple App Services share the same Key Vault / Storage permissions
var userAssignedCredential = new ManagedIdentityCredential(
    clientId: "00000000-0000-0000-0000-000000000000" // User-Assigned client ID
);

