using Azure.ResourceManager;
using Azure.ResourceManager.Authorization;
using Azure.ResourceManager.Authorization.Models;

public class RbacAssignmentService
{
    // Built-in role definition IDs (these are fixed GUIDs in Azure)
    private const string StorageBlobDataReaderRoleId = "2a2b9908-6ea1-4ae2-8e65-a410df84e7d1";
    private const string ContributorRoleId           = "b24988ac-6180-42a0-ab88-20f7382dd24c";
    private const string ReaderRoleId                = "acdd72a7-3385-48ef-bd42-f606fba81ae7";

    private readonly ArmClient _armClient;

    public RbacAssignmentService()
    {
        // Uses DefaultAzureCredential — works with managed identity in production,
        // developer credentials (az login / env vars) locally
        _armClient = new ArmClient(new DefaultAzureCredential());
    }

    /// <summary>
    /// Assigns a role to a principal at a specific resource scope.
    /// Idempotent: checks for existing assignment before creating.
    /// </summary>
    public async Task AssignRoleAsync(
        string subscriptionId,
        string resourceGroupName,
        string storageAccountName,
        string principalId,              // Object ID of the user, group, or managed identity
        string principalType = "ServicePrincipal") // User | Group | ServicePrincipal
    {
        // Build the resource scope (resource-level — narrowest, most secure)
        string resourceScope =
            $"/subscriptions/{subscriptionId}" +
            $"/resourceGroups/{resourceGroupName}" +
            $"/providers/Microsoft.Storage/storageAccounts/{storageAccountName}";

        // Full role definition ID path required by ARM
        string roleDefinitionId =
            $"/subscriptions/{subscriptionId}/providers/Microsoft.Authorization" +
            $"/roleDefinitions/{StorageBlobDataReaderRoleId}";

        var scopeId = new ResourceIdentifier(resourceScope);
        var roleAssignmentCollection = _armClient
            .GetAuthorizationRoleAssignments(scopeId);

        // Check if assignment already exists to keep this idempotent
        await foreach (var existing in roleAssignmentCollection.GetAllAsync())
        {
            if (existing.Data.PrincipalId.ToString() == principalId &&
                existing.Data.RoleDefinitionId.ToString().EndsWith(StorageBlobDataReaderRoleId))
            {
                Console.WriteLine("Role assignment already exists — skipping.");
                return;
            }
        }

